                          s4 b1 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc e_fwrite m)
    (MS (mkR (Z_to_bv 64 0xf9c0c) (Z_to_bv 64 (usp - 80)) gp (Z_to_bv 64 TP_A) t0 t1 t2 (Z_to_bv 64 2) (Z_to_bv 64 buf) v
             a1 a2 a3 a4 a5 a6 a7 p1 (Z_to_bv 64 len) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xf9c0c) fc None m (seg_rom asegs)).
